local formatTableModule = require(script.Parent.Parent.formatTable)
local formatTable = formatTableModule.formatTable

return function(plasma)
	local create = plasma.create
	return plasma.widget(function(debugger)
		local custom = debugger._customWidgets
		local style = plasma.useStyle()
		local closed = plasma
			.window({
				title = "Player Props",
				closable = true,
				maxSize = Vector2.new(352, style.panelHeight),
				minSize = Vector2.new(252, style.panelHeight),
			}, function()
				plasma.useInstance(function(ref)
					local playerProps = debugger.PlayerProps
					local filter = custom.textBox1("filter...").Text()
					filter = string.gsub(filter, "%s+", "")

					local items = {{"Group ", "Name				 ", "Count "}}
					for i, v in pairs(playerProps) do
						for j, k in pairs(v) do
							local elementType = k:GetElementType()
							if elementType == "Element" then
								local id = k:GetId()
								if filter == "" or (filter ~= "" and string.find(i, filter) or string.find(id, filter)) then
									local value = k:GetValue() or k._children[1]:GetCount()
									table.insert(items, {
										i,
										id,
										value
									})
								end
								
							end
						end
					end
					local sc = custom.scrollframe(function()
						plasma.table(items, {
							headings = true,
							selectable = false,
							font = Enum.Font.Gotham
						})
					end, {
						Size = UDim2.new(1, 0, 1, -50)
					})
				end)
			end)
			:closed()

		if closed then
			return closed
		end
		return nil
	end)
end
